use super::*;

/// Where to read back what [`record_run`] just wrote — the exact command, not a description of one.
///
/// A hub db is `<…>/projects/<key>/error.db`, and naming the KEY is what makes the suggestion match
/// what the caller typed: the operator this line exists for wrote `--project studio-code`, so handing
/// `--db /home/…/error.db` back would read as a different store. Anything else falls back to the exact
/// `--db <path>` form, which is always correct — a GUESSED key would send the reader to a store that
/// may not exist, and a suggestion that does not run is worse than a long one that does.
pub(crate) fn mem_read_back(db: &std::path::Path, source: &str) -> String {
    let key = Some(db)
        .filter(|p| p.file_name().is_some_and(|f| f == "error.db"))
        .and_then(|p| p.parent())
        .filter(|hub| hub.parent().and_then(|p| p.file_name()).is_some_and(|n| n == "projects"))
        .and_then(|hub| hub.file_name())
        .and_then(|k| k.to_str());
    match key {
        Some(k) => format!("bsc mem build --project {k} --source {source}"),
        None => format!("bsc mem build --db {} --source {source}", db.display()),
    }
}
